const polar=(cx,cy,r,a)=>[cx+r*Math.cos(a),cy+r*Math.sin(a)];
function engine(entry,variant='hero'){
 const w=(entry.headword||'אהיה').replace(/[\s״'"׳]/g,'').slice(0,5)||'אהיה';const seq=Array.from(w);const outer=[],inner=[],rays=[],radials=[],bars=[],textMarks=[];
 for(let i=0;i<18;i++){let a=i*Math.PI*2/18;let p=polar(350,240,207,a),p2=polar(350,240,i%3===0?230:217,a);radials.push(`<path d="M${p[0].toFixed(1)} ${p[1].toFixed(1)}L${p2[0].toFixed(1)} ${p2[1].toFixed(1)}" stroke="#88939a" stroke-opacity=".45" stroke-width=".8"/>`)}
 for(let i=0;i<33;i++){let a=i*2*Math.PI/33;let p=polar(350,240,156,a),q=polar(350,240,161+(i%4)*3,a);rays.push(`<path d="M${p[0].toFixed(1)} ${p[1].toFixed(1)}L${q[0].toFixed(1)} ${q[1].toFixed(1)}" stroke="#a8675d" stroke-opacity=".37" stroke-width=".7"/>`)}
 for(let i=0;i<12;i++){let a=i*2*Math.PI/12+0.2,p=polar(350,240,213,a);bars.push(`<circle cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="${i%3===0?3:1.7}" fill="${i%3===0?'#ad5146':'#a7a39b'}"/>`)}
 const anno=(entry.annotations||[]).filter(x=>x.entity).slice(0,5).map((a,i)=>escape(a.entity.name).slice(0,12));const stats=anno.length?anno:['מקורות','שיטות','אותיות'];
 for(let i=0;i<stats.length;i++){let a=(i*2*Math.PI/stats.length)+.13,p=polar(350,240,255,a);textMarks.push(`<text x="${p[0].toFixed(1)}" y="${p[1].toFixed(1)}" font-size="12" font-family="serif" text-anchor="middle" fill="#596772" opacity=".7">${stats[i]}</text>`)}
 let graphic=`<svg viewBox="0 0 680 490" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs><pattern id="dots-${variant}" width="14" height="14" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#a4a09a" opacity=".35"/></pattern></defs><rect x="0" y="0" width="680" height="490" fill="url(#dots-${variant})" opacity=".20"/><g fill="none" stroke="#7b8187" stroke-width=".8" opacity=".35"><path d="M30 240H660M350 8V477"/><path d="M100 70L600 410M96 401L612 76" stroke-dasharray="2 6"/><circle cx="350" cy="240" r="240" stroke-dasharray="2 6"/><circle cx="350" cy="240" r="153"/><circle cx="350" cy="240" r="106"/><path d="M245 135L455 345M245 345L455 135"/><rect x="305" y="196" width="90" height="90"/></g><g class="engine-orbit" fill="none" stroke="#aa5149" stroke-width=".85" opacity=".7"><circle cx="350" cy="240" r="210" stroke-dasharray="180 15 32 22 8 21"/><circle cx="350" cy="240" r="176" stroke-dasharray="76 56 13 41" stroke-width=".6"/>${radials.join('')} ${bars.join('')}</g><g class="engine-orbit reverse" fill="none" stroke="#ac776a" opacity=".54"><circle cx="350" cy="240" r="159" stroke-dasharray="3 6"/>${rays.join('')}</g><g class="engine-transit" fill="none" stroke="#a9544d" opacity=".35" stroke-width=".8"><path d="M70 385Q100 130 300 70T620 92"/><path d="M95 190C225 380 525 76 585 300"/></g><g opacity=".48" font-family="serif" font-size="10" text-anchor="middle" fill="#454e54"><text x="350" y="20">א · ב · ג · ד · ה · ו</text><text x="350" y="475">י ב צ ר ה</text><text x="20" y="235">א</text><text x="657" y="243">ת</text></g>${textMarks.join('')}<g fill="none" stroke="#b46b5b" stroke-width="1.3"><circle cx="350" cy="240" r="9"/><path d="M345 240h10M350 235v10"/><circle cx="350" cy="31" r="4" fill="#ad5146"/></g></svg>`;
 const labels=(entry.annotations||[]).filter(a=>a.entity);const activeAnnotation=variant!=='hero' && S.picked!==null && entry.key===S.entryKey ? entry.annotations?.[S.picked] : null;return `<div class="engine ${variant==='hero'?'hero-engine':''}" data-engine-key="${escape(entry.key)}">${graphic}<div class="engine-word" data-word="${escape(w)}" aria-hidden="true">${seq.map(l=>`<em>${escape(l)}</em>`).join('')}</div><span class="engine-label first">${escape(activeAnnotation?.entity?.name||labels.find(a=>a.feature==='method')?.entity?.name||'צירופי אותיות')}</span><span class="engine-label second">${escape(labels.find(a=>a.feature==='kabbalisticassociations')?.entity?.name||'מערכות של ידע')}</span><span class="engine-label third">${escape(labels.find(a=>a.feature==='numericalvalue')?.entity?.name||'תבניות וסודות')}</span><span class="engine-meta">${escape(entry.key)} / ${entry.annotation_count||0} ANNOTATIONS</span><span class="engine-index">ALEPH / LETTER MACHINE / 01</span>${variant==='hero'?`<a class="engine-hit" href="${entryUrl(entry)}" aria-label="פתח את הערך ${escape(entry.headword||'')}"><span class="sr-only">פתח את הערך ${escape(entry.headword||'')}</span></a>`:''}</div>`
}
function intro(title,desc,kicker='ZACUT / RESEARCH ENVIRONMENT',entry=null){return `<div class="page-intro"><div class="appear"><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>${engine(entry||getEntry(S.entryKey),'intro')}</div>`}
